-- EduNova v0.41.0 Phase 6 Student Finance: fee schedules, receivables, immutable ledger, cashier receipts.
CREATE TABLE IF NOT EXISTS student_fee_schedules (id VARCHAR(64) PRIMARY KEY,institution_id VARCHAR(64) NOT NULL,program_unit_id VARCHAR(64) NOT NULL,academic_year_id VARCHAR(64) NOT NULL,name VARCHAR(160) NOT NULL,currency VARCHAR(8) NOT NULL,state VARCHAR(20) NOT NULL,row_version INTEGER NOT NULL,created_by VARCHAR(64) NOT NULL,created_at TIMESTAMP NOT NULL,published_at TIMESTAMP NULL,CONSTRAINT uq_fee_schedule_scope UNIQUE(institution_id,program_unit_id,academic_year_id,name));
CREATE INDEX IF NOT EXISTS ix_fee_schedule_scope ON student_fee_schedules(institution_id,program_unit_id,academic_year_id,state);
CREATE TABLE IF NOT EXISTS student_fee_items (id VARCHAR(64) PRIMARY KEY,schedule_id VARCHAR(64) NOT NULL,code VARCHAR(64) NOT NULL,label VARCHAR(240) NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),due_on DATE NULL,mandatory BOOLEAN NOT NULL,installment_no INTEGER NOT NULL CHECK(installment_no>0),CONSTRAINT uq_fee_item_code UNIQUE(schedule_id,code));
CREATE TABLE IF NOT EXISTS student_finance_charges (id VARCHAR(64) PRIMARY KEY,institution_id VARCHAR(64) NOT NULL,student_id VARCHAR(64) NOT NULL,registration_id VARCHAR(64) NOT NULL,fee_item_id VARCHAR(64) NOT NULL,code VARCHAR(64) NOT NULL,label VARCHAR(240) NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),paid_minor INTEGER NOT NULL DEFAULT 0 CHECK(paid_minor>=0 AND paid_minor<=amount_minor),currency VARCHAR(8) NOT NULL,due_on DATE NULL,state VARCHAR(20) NOT NULL,created_at TIMESTAMP NOT NULL,CONSTRAINT uq_registration_fee_charge UNIQUE(registration_id,fee_item_id));
CREATE INDEX IF NOT EXISTS ix_finance_charges_student ON student_finance_charges(institution_id,student_id,state,due_on);
CREATE TABLE IF NOT EXISTS student_finance_ledger (id VARCHAR(64) PRIMARY KEY,institution_id VARCHAR(64) NOT NULL,student_id VARCHAR(64) NOT NULL,kind VARCHAR(20) NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency VARCHAR(8) NOT NULL,reference VARCHAR(120) NOT NULL,charge_id VARCHAR(64) NULL,actor_id VARCHAR(64) NOT NULL,note VARCHAR(1000) NULL,created_at TIMESTAMP NOT NULL,CONSTRAINT uq_finance_reference UNIQUE(institution_id,reference,charge_id,kind));
CREATE INDEX IF NOT EXISTS ix_finance_ledger_student ON student_finance_ledger(institution_id,student_id,created_at);
CREATE TABLE IF NOT EXISTS student_finance_receipts (id VARCHAR(64) PRIMARY KEY,institution_id VARCHAR(64) NOT NULL,student_id VARCHAR(64) NOT NULL,reference VARCHAR(120) NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency VARCHAR(8) NOT NULL,payment_method VARCHAR(32) NOT NULL,external_reference VARCHAR(160) NULL,issued_by VARCHAR(64) NOT NULL,issued_at TIMESTAMP NOT NULL,reversed BOOLEAN NOT NULL DEFAULT FALSE,CONSTRAINT uq_finance_receipt_ref UNIQUE(institution_id,reference),CONSTRAINT uq_finance_external_ref UNIQUE(institution_id,external_reference));
